item.command:
/usr/bin/zsh -lc "python3 - <<'PY'
import json
for fn in ['validation.json','architecture-review.json','design-review.json','report.json','engineering-views.json']:
 p=json.load(open('build/outputs/'+fn)); print('\\n'+fn)
 print('status',p.get('status'),'states',p.get('states'))
 print('dims',[(x.get('component') or x.get('name'),x.get('dimensions_mm') or x.get('bbox_mm')) for x in p.get('components',[])])
 if p.get('flow_paths'): print('flows',p['flow_paths'])
 if 'views' in p: print('views',[(v['view'],v.get('status','PASS')) for v in p['views']])
PY"

